  wavesTarget.sourceLayoutPhysics10.push({type:'figure',record:rope20},{type:'paragraph',index:first20},{type:'paragraph',index:first20+1},{type:'paragraph',index:first20+2},{type:'figureColumns',mainIndices:[first20+3,first20+4],figures:[em20]});
  wavesTarget.sourceReferences.push({pdf:'10thphysics1.pdf',pdfPage:20,printedPage:'15'});
